28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date", columnDefinition = "DATE")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private boolean bulkSignupWarning;
78	
79	    @Column(name = "possible_duplicate")
80	    private boolean possibleDuplicate;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    /**
117	     * Stores the email in its canonical lower-cased form so it is always persisted and
118	     * returned lower-cased, regardless of the casing supplied by the client.
119	     */
120	    public void setEmail(String email) {
121	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
122	    }
123	
124	    public String getPostcode() {
125	        return this.postcode;
126	    }
127	
128	    public void setPostcode(String postcode) {
129	        this.postcode = postcode;
130	    }
131	
132	    public LocalDate getRegistrationDate() {
133	        return this.registrationDate;
134	    }
135	
136	    public void setRegistrationDate(LocalDate registrationDate) {
137	        this.registrationDate = registrationDate;
138	    }
139	
140	    public LocalDate getBirthDate() {
141	        return this.birthDate;
142	    }
143	
144	    public void setBirthDate(LocalDate birthDate) {
145	        this.birthDate = birthDate;
146	    }
147	
148	    /**
149	     * The owner's age band derived from {@link #birthDate} against {@link #registrationDate}, or
150	     * {@code null} when no birth date was supplied.
151	     */
152	    @Transient
153	    public AgeBand getAgeBand() {
154	        return this.birthDate == null ? null : AgeBand.of(this.birthDate, this.registrationDate);
155	    }
156	
157	    public String getCustomerCode() {
158	        return this.customerCode;
159	    }
160	
161	    public void setCustomerCode(String customerCode) {
162	        this.customerCode = customerCode;
163	    }
164	
165	    public String getHouseholdId() {
166	        return this.householdId;
167	    }
168	
169	    public void setHouseholdId(String householdId) {
170	        this.householdId = householdId;
171	    }
172	
173	    public Integer getNamesakeCount() {
174	        return this.namesakeCount;
175	    }
176	
177	    public void setNamesakeCount(Integer namesakeCount) {
178	        this.namesakeCount = namesakeCount;
179	    }
180	
181	    public Integer getHouseholdSize() {
182	        return this.householdSize;
183	    }
184	
185	    public void setHouseholdSize(Integer householdSize) {
186	        this.householdSize = householdSize;
187	    }
188	
189	    public boolean isBulkSignupWarning() {
190	        return this.bulkSignupWarning;
191	    }
192	
193	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
194	        this.bulkSignupWarning = bulkSignupWarning;
195	    }
196	
197	    public boolean isPossibleDuplicate() {
198	        return this.possibleDuplicate;
199	    }
200	
201	    public void setPossibleDuplicate(boolean possibleDuplicate) {
202	        this.possibleDuplicate = possibleDuplicate;
203	    }
204	
205	    public Integer getPossibleDuplicateOf() {
206	        return this.possibleDuplicateOf;
207	    }
208	
209	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
210	        this.possibleDuplicateOf = possibleDuplicateOf;
211	    }
212	
213	    /**
214	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
215	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
216	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
217	     * are duplicates only when their whole identity keys are equal, so members of the same household
218	     * with different telephones (or an owner reusing only a telephone or only an email) remain
219	     * distinct.
220	     */
221	    @Transient
222	    public String getIdentityKey() {
223	        return this.telephone + "|"
224	            + (this.email == null ? "" : this.email) + "|"
225	            + (this.householdId == null ? "" : this.householdId);
226	    }
227	
228	    /**
229	     * On first persist, default the registration date to the server's current date when the
230	     * client did not supply one, then roll the effective date forward so it always falls on a
231	     * business day (a weekend moves to the following Monday).
232	     */
233	    @PrePersist
234	    private void defaultRegistrationDate() {
235	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
236	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
237	    }
238	
239	    protected Set<Pet> getPetsInternal() {
240	        if (this.pets == null) {
241	            this.pets = new HashSet<>();
242	        }
243	        return this.pets;
244	    }
245	
246	    protected void setPetsInternal(Set<Pet> pets) {
247	        this.pets = pets;
248	    }
249	
250	    public List<Pet> getPets() {
251	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
252	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
253	        return Collections.unmodifiableList(sortedPets);
254	    }
255	
256	    public void setPets(List<Pet> pets) {
257	        this.pets = new HashSet<>(pets);
258	    }
259	
260	    public void addPet(Pet pet) {
261	        getPetsInternal().add(pet);
262	        pet.setOwner(this);
263	    }
264	
265	    /**
266	     * Return the Pet with the given name, or null if none found for this Owner.
267	     *
268	     * @param name to test
269	     * @return true if pet name is already in use
270	     */
271	    public Pet getPet(String name) {
272	        return getPet(name, false);
273	    }
274	
275	    /**
276	     * Return the Pet with the given name, or null if none found for this Owner.
277	     *
278	     * @param name to test
279	     * @return true if pet name is already in use
280	     */
281	    public Pet getPet(String name, boolean ignoreNew) {
282	        name = name.toLowerCase();
283	        for (Pet pet : getPetsInternal()) {
284	            if (!ignoreNew || !pet.isNew()) {
285	                String compName = pet.getName();
286	                compName = compName.toLowerCase();
287	                if (compName.equals(name)) {
288	                    return pet;
289	                }
290	            }
291	        }
292	        return null;
293	    }
294	
295	    public Pet getPet(Integer petId) {
296	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
297	    }
298	
299	    @Override
300	    public String toString() {
301	        return new ToStringCreator(this)
302	
303	            .append("id", this.getId())
304	            .append("new", this.isNew())
305	            .append("lastName", this.getLastName())
306	            .append("firstName", this.getFirstName())
307	            .append("address", this.address)
308	            .append("city", this.city)
309	            .append("telephone", this.telephone)
310	            .append("email", this.email)
311	            .toString();
312	    }
313	}
