244	        if (owner.isNew() && owner.getCustomerCode() == null) {
245	            owner.setCustomerCode(customerCodeGenerator.generate(
246	                owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
247	        }
248	        ownerRepository.save(owner);
249	
250	    }
251	
252	    @Override
253	    @Transactional(readOnly = true)
254	    public boolean existsOwnerWithIdentityKey(Owner owner) throws DataAccessException {
255	        String identityKey = owner.getIdentityKey();
256	        // Owners can only share an identity key when they share a (normalized) telephone, so it is
257	        // enough to compare against the owners already stored with the same telephone.
258	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
259	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
260	    }
261	
262	    /**
263	     * Find an existing owner that this (not yet persisted) owner soft-matches: one sharing its last
264	     * name (ignoring case) and postcode but carrying a different telephone, so it is not a hard
265	     * identity-key duplicate. Returns the matching owner's id (the lowest when several match), or
266	     * {@code null} when the owner has no postcode or nothing matches.
267	     */
268	    @Override
269	    @Transactional(readOnly = true)
270	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
271	        if (owner.getPostcode() == null) {
272	            return null;
273	        }
274	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
275	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
276	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
277	            .map(Owner::getId)
278	            .min(Integer::compareTo)
279	            .orElse(null);
280	    }
281	
282	    @Override
283	    @Transactional(readOnly = true)
284	    public boolean existsOwnerInHousehold(String lastName, String address) throws DataAccessException {
285	        return !findHouseholdMembers(lastName, address).isEmpty();
286	    }
287	
288	    /**
289	     * The maximum number of owners allowed in a single city; once a city holds this many
290	     * owners it is considered at capacity and no further owners may be created there.
291	     */
292	    static final long CITY_CAPACITY = 50;
293	
294	    @Override
295	    @Transactional(readOnly = true)
296	    public boolean isCityAtCapacity(String city) throws DataAccessException {
297	        return ownerRepository.countByCityIgnoreCase(city) >= CITY_CAPACITY;
298	    }
299	
300	    /**
301	     * The maximum number of owners that may be created in a single day; once this many owners
302	     * have already been registered on a given business day no further owners may be created for
303	     * that day.
304	     */
305	    static final long DAILY_OWNER_LIMIT = 100;
306	
307	    @Override
308	    public boolean isRegistrationDateInFuture(LocalDate registrationDate) {
309	        return registrationDate != null && registrationDate.isAfter(LocalDate.now());
310	    }
311	
312	    @Override
313	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
314	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
315	        return BusinessDay.rollForward(effectiveDate);
316	    }
317	
318	    @Override
319	    @Transactional(readOnly = true)
320	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
321	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
322	    }
323	
324	    /**
325	     * The number of owners that may be registered on a given day before further sign-ups for that
326	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
327	     * the day, subsequent creates carry the warning.
328	     */
329	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
330	
331	    @Override
332	    @Transactional(readOnly = true)
333	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
334	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
335	    }
336	
337	    @Override
338	    @Transactional(readOnly = true)
339	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
340	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
341	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
342	            .count();
343	    }
344	
345	    @Override
346	    @Transactional
347	    public String assignHousehold(Owner owner) throws DataAccessException {
348	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
349	        String householdId = members.stream()
350	            .map(Owner::getHouseholdId)
351	            .filter(Objects::nonNull)
352	            .findFirst()
353	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
354	        owner.setHouseholdId(householdId);
355	        for (Owner member : members) {
356	            if (member.getHouseholdId() == null) {
357	                member.setHouseholdId(householdId);
358	                ownerRepository.save(member);
359	            }
360	        }
361	        return householdId;
362	    }
363	
364	    /**
365	     * The number of members the owner's household will have once this (not yet persisted) owner is
366	     * created: the existing members sharing its last name and canonical address, plus the owner itself.
367	     */
368	    @Override
369	    @Transactional(readOnly = true)
370	    public long countHouseholdMembers(String lastName, String address) throws DataAccessException {
371	        return findHouseholdMembers(lastName, address).size() + 1;
372	    }
373	
374	    /**
375	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
376	     * name (ignoring case) and the same canonical address.
377	     */
378	    private List<Owner> findHouseholdMembers(String lastName, String address) {
379	        String canonicalAddress = householdIdGenerator.canonical(address);
380	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
381	            .filter(owner -> householdIdGenerator.canonical(owner.getAddress()).equals(canonicalAddress))
382	            .toList();
383	    }
384	
385	    @Override
386	    @Transactional(readOnly = true)
387	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
388	        return ownerRepository.findByLastName(lastName);
389	    }
390	
391	    @Override
392	    @Transactional(readOnly = true)
393	    public Collection<Visit> findVisitsByPetId(int petId) {
394	        return visitRepository.findByPetId(petId);
395	    }
396	
397	    @Override
398	    @Transactional(readOnly = true)
399	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
400	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
401	    }
402	
403	    private <T> T findEntityById(Supplier<T> supplier) {
404	        try {
405	            return supplier.get();
406	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
407	            // Just ignore not found exceptions for Jdbc/Jpa realization
408	            return null;
409	        }
410	    }
411	
412	}
