1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
13	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
14	import org.springframework.samples.petclinic.util.Luhn;
15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(computeCheckDigit(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
32	    @Mapping(target = "ageBand", expression = "java(resolveAgeBand(owner))")
33	    @Mapping(target = "identityKey", expression = "java(owner.getIdentityKey())")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    Owner toOwner(OwnerDto ownerDto);
37	
38	    /**
39	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
40	     */
41	    default String formatDisplayName(Owner owner) {
42	        return owner.getLastName() + ", " + owner.getFirstName();
43	    }
44	
45	    /**
46	     * Formats the owner's initials as the upper-cased first letters of firstName and
47	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
48	     */
49	    default String formatInitials(Owner owner) {
50	        return initial(owner.getFirstName()) + initial(owner.getLastName());
51	    }
52	
53	    /** The upper-cased first letter of {@code name} followed by a dot. */
54	    private String initial(String name) {
55	        return Character.toUpperCase(name.charAt(0)) + ".";
56	    }
57	
58	    /**
59	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
60	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
61	     * region encoded in the owner's identity.
62	     */
63	    default String resolveLocality(Owner owner) {
64	        String customerCode = owner.getCustomerCode();
65	        return customerCode.substring(0, customerCode.indexOf('-'));
66	    }
67	
68	    /**
69	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
70	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
71	     */
72	    default String formatMembershipNumber(Owner owner) {
73	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
74	    }
75	
76	    /**
77	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
78	     */
79	    default Integer computeCheckDigit(Owner owner) {
80	        return Luhn.checkDigit(owner.getCustomerCode());
81	    }
82	
83	    /**
84	     * Resolves the owner's numeric membership level, assigned on creation: starts at {@code 1},
85	     * plus {@code 1} when an email is present, plus {@code 1} when the owner has no namesakes
86	     * (namesakeCount is 0), capped at {@code 3} (level {@code 4} is reserved for tenure).
87	     */
88	    default Integer resolveMembershipLevel(Owner owner) {
89	        int level = 1;
90	        if (hasEmail(owner)) {
91	            level++;
92	        }
93	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
94	            level++;
95	        }
96	        return Math.min(level, 3);
97	    }
98	
99	    /**
100	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
101	     * present, otherwise {@code "PHONE"}.
102	     */
103	    default String resolveContactPreference(Owner owner) {
104	        return hasEmail(owner) ? "EMAIL" : "PHONE";
105	    }
106	
107	    /** Whether the owner has a non-blank email address. */
108	    private boolean hasEmail(Owner owner) {
109	        return owner.getEmail() != null && !owner.getEmail().isBlank();
110	    }
111	
112	    /**
113	     * Resolves the owner's age band (as a string) from its birth date against its registration
114	     * date, or {@code null} when the owner has no birth date.
115	     */
116	    default String resolveAgeBand(Owner owner) {
117	        return owner.getAgeBand() == null ? null : owner.getAgeBand().name();
118	    }
119	
120	    @Mapping(target = "id", ignore = true)
121	    @Mapping(target = "pets", ignore = true)
122	    @Mapping(target = "householdId", ignore = true)
123	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
124	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
125	    Owner toOwner(OwnerFieldsDto ownerDto);
126	
127	    /**
128	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
129	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
130	     */
131	    @Named("normalizeAddress")
132	    default String normalizeAddress(String address) {
133	        return AddressNormalizer.normalize(address);
134	    }
135	
136	    /**
137	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
138	     * the raw value normalizes to a valid E.164 number.
139	     */
140	    @Named("normalizeTelephone")
141	    default String normalizeTelephone(String telephone) {
142	        return TelephoneNormalizer.toE164(telephone);
143	    }
144	
145	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
146	
147	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
148	
149	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
150	        OwnerPageDto ownerPageDto = new OwnerPageDto();
151	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
152	        ownerPageDto.setPage(ownerPage.getNumber());
153	        ownerPageDto.setSize(ownerPage.getSize());
154	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
155	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
156	        return ownerPageDto;
157	    }
158	}
