6	/**
7	 * Normalizes a postal address to its canonical stored form.
8	 *
9	 * <p>The raw value is trimmed, its internal runs of whitespace are collapsed to a single space
10	 * and it is upper-cased. Each resulting word is then checked against a small table of common
11	 * abbreviations ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) and expanded to
12	 * its full form. Applying this consistently means addresses that differ only in casing, spacing or
13	 * abbreviation are stored — and therefore compared — as the same value.
14	 */
15	public final class AddressNormalizer {
16	
17	    /** Whole-word abbreviations expanded to their full form (keyed by their upper-cased token). */
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	        "ST", "STREET",
20	        "RD", "ROAD",
21	        "AVE", "AVENUE");
22	
23	    private AddressNormalizer() {
24	    }
25	
26	    /**
27	     * Convert a raw address to its normalized form.
28	     *
29	     * @param address the raw address, possibly {@code null} or containing irregular whitespace,
30	     *                casing or abbreviations
31	     * @return the normalized address (trimmed, whitespace-collapsed, upper-cased and with common
32	     *         abbreviations expanded), or {@code null} when the input is {@code null}
33	     */
34	    public static String normalize(String address) {
35	        if (address == null) {
36	            return null;
37	        }
38	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
39	        if (collapsed.isEmpty()) {
40	            return collapsed;
41	        }
42	        String[] words = collapsed.split(" ");
43	        for (int i = 0; i < words.length; i++) {
44	            words[i] = ABBREVIATIONS.getOrDefault(words[i], words[i]);
45	        }
46	        return String.join(" ", words);
47	    }
48	}
