package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class TmpHouseholdTest extends AcceptanceBase {

	@Test
	void secondSameHouseholdWithoutShareIsRejected() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		createOwnerOk(a);

		ObjectNode b = ownerNode(); // unique phone/name-first, same lastName+postcode
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void declaredMemberCreatedAndNotFlagged() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		int idA = createOwnerOk(a);

		ObjectNode b = ownerNode();
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		b.put("sharesHousehold", true);
		int idB = createOwnerOk(b);

		JsonNode nb = fetchOwner(idB);
		assertEquals(fetchOwner(idA).get("householdId").asText(), nb.get("householdId").asText());
		assertFalse(nb.get("possibleDuplicate").asBoolean());
		// household size counts both members
		assertEquals(2, nb.get("householdSize").asInt());
	}
}

